style.css:
@-moz-document domain("chatgpt.com"), url-prefix("https://chatgpt.com/") {
/* Nuke Tailwind max-widths everywhere */
  [class*="max-w-"],
  [class*="sm:max-w-"],
  [class*="md:max-w-"],
  [class*="lg:max-w-"],
  [class*="xl:max-w-"],
  [class*="2xl:max-w-"] {
    max-width: none !important;
  }

  /* Expand the actual chat column */
  main,
  article,
  .prose,
  [class*="prose"],
  .markdown,
  .text-base,
  .flex,
  .relative {
    width: 100% !important;
    max-width: 100% !important;
  }
}
